28	static void fmt_f1(char * buf, size_t n, float v)
29	{
30	    int vi = (int)v;
31	    int vf = (int)((v - (float)vi) * 10.0f);
32	    if(vf < 0) vf = -vf;
33	    lv_snprintf(buf, n, "%d.%d", vi, vf);
34	}
