36	/*
37	 * LVGL 9 chart styles line width / point size per chart, not per series.
38	 * lv_chart.c draw_series() iterates the series list tail→head and assigns
39	 * base.id1 = (series_count - 1) down to 0 in draw order. Series are added
40	 * at the list tail, so the anomaly series (added last, drawn FIRST) carries
41	 * id1 == VG_TREND_SERIES_N - 1, and the main data series (added first,
42	 * drawn last) carries id1 == 0. Hide the anomaly series' connecting line
43	 * and the dot tasks of every other series so only red over-threshold dots
44	 * remain (manual 6.5).
45	 */
46	static void chart_draw_task_cb(lv_event_t * e)
47	{
48	    lv_draw_task_t * task = lv_event_get_draw_task(e);
49	    lv_draw_dsc_base_t * base = (lv_draw_dsc_base_t *)task->draw_dsc;
50	
51	    if(task->type == LV_DRAW_TASK_TYPE_LINE && base->part == LV_PART_ITEMS) {
52	        if(base->id1 == (uint32_t)(VG_TREND_SERIES_N - 1)) {
53	            lv_draw_line_dsc_t * dsc = (lv_draw_line_dsc_t *)task->draw_dsc;
54	            dsc->width = 0;
55	            dsc->opa = LV_OPA_TRANSP;
56	        }
57	    }
58	    else if(task->type == LV_DRAW_TASK_TYPE_FILL && base->part == LV_PART_INDICATOR) {
59	        if(base->id1 != (uint32_t)(VG_TREND_SERIES_N - 1)) {
60	            lv_draw_rect_dsc_t * dsc = (lv_draw_rect_dsc_t *)task->draw_dsc;
61	            dsc->bg_opa = LV_OPA_TRANSP;
62	        }
63	    }
64	}
