71	static uint32_t window_offset(uint32_t count)
72	{
73	    if(s_trend.window_min != 1) return 0;
74	    if((uint32_t)VG_HISTORY_LEN < count) return 0;
75	    return (uint32_t)VG_HISTORY_LEN - count;
76	}
