78	static void refresh_trend(void * user)
79	{
80	    const vg_sensor_t * s;
81	    char buf[64];
82	    char a[16], b[16], c[16];
83	    uint32_t i;
84	    uint32_t count;
85	    uint32_t offset;
86	    LV_UNUSED(user);
87	    if(vg_nav_current() != VG_PAGE_TREND) return;
88	    if(s_trend.root == NULL || !lv_obj_is_valid(s_trend.root)) return;
89	    s = vg_model_get_selected_sensor();
90	    if(s == NULL || s_trend.chart == NULL) return;
91	
92	    if(s->online) {
93	        fmt_f1(a, sizeof(a), s->value);
94	        lv_snprintf(buf, sizeof(buf), "%s %s", a, s->unit);
95	    }
96	    else {
97	        lv_snprintf(buf, sizeof(buf), "-- %s", s->unit);
98	    }
99	    lv_label_set_text(s_trend.value_lab, buf);
100	    lv_obj_set_style_text_color(s_trend.value_lab, vg_color_severity(s->severity), 0);
101	
102	    fmt_f1(b, sizeof(b), s->thr_warn);
103	    fmt_f1(c, sizeof(c), s->thr_crit);
104	    lv_snprintf(buf, sizeof(buf), "阈值 预警%s / 严重%s · 最近 %d 分钟",
105	                b, c, s_trend.window_min);
106	    lv_label_set_text(s_trend.meta_lab, buf);
107	
108	    {
109	        int32_t min_v = (int32_t)((s->thr_low - 5.0f) * 10.0f);
110	        int32_t max_v = (int32_t)((s->thr_crit + 10.0f) * 10.0f);
111	        if(max_v <= min_v) max_v = min_v + 200;
112	        lv_chart_set_range(s_trend.chart, LV_CHART_AXIS_PRIMARY_Y, min_v, max_v);
113	    }
114	
115	    count = window_count();
116	    offset = window_offset(count);
117	    if(offset + count > (uint32_t)s->history_len) {
118	        offset = 0;
119	        count = (uint32_t)s->history_len;
120	    }
121	    lv_chart_set_point_count(s_trend.chart, count);
122	    for(i = 0; i < count; i++) {
123	        float v = s->history[offset + i];
124	        lv_chart_set_value_by_id(s_trend.chart, s_trend.ser, i, (int32_t)(v * 10.0f));
125	        lv_chart_set_value_by_id(s_trend.chart, s_trend.thr_warn, i, (int32_t)(s->thr_warn * 10.0f));
126	        lv_chart_set_value_by_id(s_trend.chart, s_trend.thr_crit, i, (int32_t)(s->thr_crit * 10.0f));
127	        /* red marker above warn threshold, otherwise no point */
128	        lv_chart_set_value_by_id(s_trend.chart, s_trend.anomaly, i,
129	                                 v > s->thr_warn ? (int32_t)(v * 10.0f) : LV_CHART_POINT_NONE);
130	    }
131	    lv_chart_refresh(s_trend.chart);
132	}
