    vg_model_set_scenario(VG_SCENARIO_NORMAL);
    pump(30);
    dump_ppm(out_dir, "05_alarm_empty");
    print_alarms();
    ok &= expect(vg_model_active_alarm_count() == 0, "normal scenario clears all episodes");

