}

static void indev_read_cb(lv_indev_t * indev, lv_indev_data_t * data)
{
    LV_UNUSED(indev);
    if(!s_pressed && s_queue_n > 0) {
        s_active = s_queue[0];
        memmove(&s_queue[0], &s_queue[1], sizeof(click_t) * (unsigned)(s_queue_n - 1));
        s_queue_n--;
